@Override
    public void tick() {
        super.tick();
        if (jumpDelay > 0) {
            jumpDelay--;
        } else if (jumpDelay == 0) {
            jumpDelay = 20;
            this.playSound(SoundEvents.GOAT_DEATH, 2f, 1f + random.nextFloat() * .2f);
            if (level.isClientSide) {
                animationToPlay = RawAnimation.begin().thenPlay("scapegoat_run_accent");
            }
        }
        if (tickCount % 5 == 0) {
            poofParticles(1, 1);
        }
        if (durationRemaining > 0) {
            if (--durationRemaining == 0) {
                poofAndDiscard();
            }
        }
    }

@Override
    public void onCast(Level world, int spellLevel, LivingEntity entity, CastSource castSource, MagicData playerMagicData) {
        super.onCast(world, spellLevel, entity, castSource, playerMagicData);
        Vec3 targetPos = Utils.moveToRelativeGroundLevel(world, Utils.raycastForBlock(world, entity.getEyePosition(), entity.getEyePosition().add(entity.getForward().scale(getRange(spellLevel, entity))), ClipContext.Fluid.NONE).getLocation(), 4, 24);
        ScapegoatEntity goat = new ScapegoatEntity(world);
        goat.setOwner(entity);
        goat.setTargetPos(BlockPos.containing(targetPos));
        float y = entity.getYRot();
        goat.setYBodyRot(y);
        goat.yBodyRotO = y;
        goat.setYRot(y);
        goat.yRotO = y;
        goat.yHeadRot = y;
        goat.yHeadRotO = y;
        //todo: clip?
        goat.moveTo(entity.getEyePosition().add(entity.getForward().scale(2)));
        goat.getAttributes().getInstance(Attributes.MAX_HEALTH).setBaseValue(getGoatHealth(spellLevel, entity));
        goat.setHealth(goat.getMaxHealth());
        goat.poofParticles(20, 1f);
        // todo: expose to tootip/power scaling?
        goat.setDurationRemaining(20 * 15);
        goat.invulnerableTime = 60;
        world.addFreshEntity(goat);
        Utils.performTaunt(goat, 12f, Utils.tauntPredicate(entity));
    }

public static Predicate<Entity> tauntPredicate(Entity taunter) {
        return entity -> (entity instanceof Enemy ^ taunter instanceof Enemy && !taunter.isAlliedTo(entity))
                || ((taunter instanceof LivingEntity livingEntity && entity instanceof NeutralMob neutralMob) && neutralMob.isAngryAt(livingEntity));
    }

public static void performTaunt(LivingEntity newTarget, float range, Predicate<Entity> selector) {
        performTaunt(newTarget, newTarget.level.getEntities(newTarget, newTarget.getBoundingBox().inflate(range, range, range),
                entity -> entity.distanceToSqr(newTarget) < range * range && selector.test(entity)));
    }

public static void performTaunt(LivingEntity newTarget, List<Entity> targets) {
        targets.forEach(entity -> {
            if (entity instanceof Mob tauntmob) {
                MagicManager.spawnParticles(tauntmob.level, ParticleTypes.ANGRY_VILLAGER, tauntmob.getX(), tauntmob.getEyeY() + (tauntmob.getBoundingBox().maxY - tauntmob.getEyeY()) * 2, tauntmob.getZ(), 5, 0.3, 0.3, 0.3, 0, false);
                tauntmob.setTarget(newTarget);
            }
        });
    }

@Override
    public boolean hurt(DamageSource source, float amount) {
        if (!DamageSources.isFriendlyFireBetween(source.getEntity(), this.getOwner()) && super.hurt(source, amount)) {
            if (level instanceof ServerLevel serverLevel) {
                poofParticles(10, 0.4f);
            }
            return true;
        }
        return false;
    }

@Override
    public void die(DamageSource damageSource) {
        // preserve event firing with super call, but immediately discard without animation
        super.die(damageSource);
        if (dead) {
            poofAndDiscard();
        }
    }

@Nullable
    public Entity getOwner() {
        if (this.cachedOwner != null && !this.cachedOwner.isRemoved()) {
            return this.cachedOwner;
        } else if (this.ownerUUID != null && this.level instanceof ServerLevel serverlevel) {
            this.cachedOwner = serverlevel.getEntity(this.ownerUUID);
            return this.cachedOwner;
        } else {
            return null;
        }
    }

public void setOwner(@Nullable Entity owner) {
        if (owner != null) {
            this.ownerUUID = owner.getUUID();
            this.cachedOwner = owner;
        }
    }

public void poofAndDiscard() {
        if (level instanceof ServerLevel serverLevel) {
            poofParticles(30, 1f);
            discard();
        }
    }

@Override
    public void onAntiMagic(MagicData playerMagicData) {
        poofAndDiscard();
    }

@Override
    public void addAdditionalSaveData(CompoundTag compound) {
        super.addAdditionalSaveData(compound);
        if (this.ownerUUID != null) {
            compound.putUUID("Owner", this.ownerUUID);
        }
        if (this.targetPos != null) {
            compound.put("scapegoat_target", NbtUtils.writeBlockPos(this.targetPos));
        }
        if (durationRemaining > 0) {
            compound.putInt("duration_remaining", durationRemaining);
        }
    }

@Override
    public void readAdditionalSaveData(CompoundTag compound) {
        super.readAdditionalSaveData(compound);
        if (compound.hasUUID("Owner")) {
            this.ownerUUID = compound.getUUID("Owner");
            this.cachedOwner = null;
        }
        NbtUtils.readBlockPos(compound, "scapegoat_target").ifPresent(p_325838_ -> this.targetPos = p_325838_);
        this.durationRemaining = compound.getInt("duration_remaining");
    }

@Override
    public boolean hurt(DamageSource pSource, float pAmount) {
        if (!level.isClientSide) {
            if (!parentEntity.hurtThisTick) {
                parentEntity.takeDamage(pSource, pAmount, this.getBoundingBox().getCenter());
                parentEntity.hurtThisTick = true;
            }
        }
        return false;
    }

@Override
    public void onCast(Level level, int spellLevel, LivingEntity entity, CastSource castSource, MagicData playerMagicData) {
        ShieldEntity shield = new ShieldEntity(level, getShieldHP(spellLevel, entity));
        Vec3 spawn = RaycastBuilder.begin(level, entity)
                .range(3)
                .checkForBlocks(true)
                .build()
                .getLocation();
        shield.setPos(spawn);
        shield.setRotation(entity.getXRot(), entity.getYRot());
        level.addFreshEntity(shield);
