@Override
    public void tick() {
        if (tickCount < waitTime) {
            if (this.target != null)
                setPos(this.target.position());
        } else if (tickCount == waitTime) {
            this.playSound(SoundRegistry.DEVOUR_BITE.get(), 2, 1);
        } else if (tickCount == warmupTime) {
            if (level.isClientSide) {
                float y = this.getYRot();
                int countPerSide = 25;
                //These particles were not at all what I intended. But they're cooler. no clue how it works
                for (int i = -countPerSide; i < countPerSide; i++) {
                    Vec3 motion = new Vec3(0, Math.abs(countPerSide) - i, countPerSide * .5f).yRot(y).normalize().multiply(.4f, .8f, .4f);
                    level.addParticle(ParticleHelper.BLOOD, getX(), getY() + .5f, getZ(), motion.x, motion.y, motion.z);
                }
            } else {
                checkHits();
            }
        } else if (tickCount > deathTime)
            discard();
    }

@Override
    protected Vec3 getInflation() {
        return new Vec3(2, 2, 2);
    }

@Override
    public boolean shouldBeSaved() {
        return false;
    }

protected void checkHits() {
        if (level.isClientSide)
            return;
        List<LivingEntity> targets = this.level.getEntitiesOfClass(LivingEntity.class, this.getBoundingBox().inflate(this.getInflation().x, this.getInflation().y, this.getInflation().z));
        boolean hit = false;
        var radiusSqr = getRadius();
        radiusSqr *= radiusSqr;
        for (LivingEntity target : targets) {
            if (canHitEntity(target) && (!isCircular() || target.distanceToSqr(this) < radiusSqr)) {
                if (canHitTargetForGroundContext(target)) {
                    applyEffect(target);
                    hit = true;
                }
            }
        }
        if (hit) {
            this.setRadius(getRadius() + radiusOnUse);
            this.duration += durationOnUse;
            onPostHit();
        }
    }

@Override
    protected boolean canHitEntity(Entity pTarget) {
        return (getOwner() == null || (pTarget != getOwner() && !getOwner().isAlliedTo(pTarget))) && super.canHitEntity(pTarget);
    }

protected boolean canHitTargetForGroundContext(LivingEntity target) {
        return target.onGround() || target.getY() - getY() < .5;
    }
